// Each import is stored as its own module entry whose loader is not `js`.
// The loader enum gained `jsonc` at 7 in Bun 1.2.5, which renumbered every
// value above it, so these entries tell the two numberings apart.
// data.db, addon.node and module.wasm are generated by build.sh.
import db from "./data.db" with { type: "sqlite", embed: "true" };
import addon from "./addon.node";
import wasm from "./module.wasm";
import page from "./page.html";
import notes from "./notes.txt" with { type: "text" };

console.log(db, addon, wasm, page, notes);
